<?php declare(strict_types=1); namespace Annam; $title='Checkout'; ?>
<section class="wrap php-store-section php-checkout-page"><div class="page-intro"><p class="section-kicker">1 · Delivery details</p><h1>Good food, delivered to you.</h1></div><p>Meals require an approved delivery area. Snacks outside Chennai use courier delivery; courier charges are payable separately after dispatch.</p><div class="checkout-layout"><form method="post" id="delivery-details" class="checkout-card checkout-form" data-checkout-delivery data-meal-delivery="<?= ($quote['cart']['kind']??'')==='scheduled'?'1':'0' ?>"><?= csrf() ?><?php if(!empty($form_error)):?><div class="checkout-errors php-error" role="alert" tabindex="-1" id="checkout-errors"><?= e($form_error) ?></div><?php endif;?><div class="checkout-fields"><?php foreach(['name'=>'Full name','phone'=>'Mobile number','email'=>'Email (optional)','line1'=>'Door number & street','line2'=>'Apartment / locality (optional)','landmark'=>'Landmark (optional)','city'=>'City','state'=>'State / region','country'=>'Country','pincode'=>'Pincode / postal code'] as $key=>$label): ?><label class="checkout-field"><span><?= e($label) ?></span><input class="checkout-input" name="<?= e($key) ?>" value="<?= e($_POST[$key]??(['country'=>'India','state'=>'Tamil Nadu','pincode'=>$_SESSION['cart']['pincode']??''][$key]??'')) ?>" <?= in_array($key,['email','line2','landmark'])?'':'required' ?> <?= $key==='email'?'type="email"':($key==='phone'?'type="tel" autocomplete="tel" aria-describedby="phone-help"':'') ?> maxlength="<?= $key==='pincode'?20:($key==='phone'?20:200) ?>"><?php if($key==='phone'):?><small id="phone-help">Enter 10 digits, or include the country code, e.g. +91 98765 43210.</small><?php endif;?></label><?php endforeach; ?>
<label class="checkout-field checkout-field-wide" data-checkout-area <?= count($deliveryState['areas'])>1?'':'hidden' ?>><span>Choose your delivery area</span><select class="checkout-input" name="zone_id" <?= count($deliveryState['areas'])>1?'required':'' ?> <?= !$deliveryState['areas']?'disabled':'' ?>><option value="">Choose your area</option><?php foreach($deliveryState['areas'] as $area):?><option value="<?= e($area['id']) ?>" <?= (string)($deliveryState['selected']??'')===(string)$area['id']?'selected':'' ?>><?= e($area['name']) ?> — <?= money(Money::decimal($area['fee'])) ?> delivery</option><?php endforeach;?></select><small>Choose the area for your address. The delivery charge depends on this choice.</small></label><p class="checkout-note checkout-field-wide" data-delivery-feedback role="status" aria-live="polite"><?= e($deliveryState['error']) ?></p>
<label class="checkout-field checkout-field-wide"><span>Payment</span><select class="checkout-input" name="payment_method" required><?php foreach($choices as $key=>$label): ?><option value="<?= e($key) ?>" <?= (string)($_POST['payment_method']??'')===(string)$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label></div><p><?= !empty($store->config['features']['checkout_test_mode'])?'Preview TEST checkout: no online charge will be made. Choose the temporary manual payment option to test this order.':(!$choices?'Online payment is currently unavailable. Please try again later.':'Pay online to confirm your order.') ?></p><p>Items subtotal: <strong><?= Money::display($quote['subtotal']) ?></strong>. Delivery and applicable taxes appear on the next step.</p><p>Use “Review &amp; place order” below to check your final total.</p></form><aside class="checkout-card summary"><h2>Your order</h2><?php foreach($quote['lines'] as $line):?><p class="php-total"><span><?= e($line['quantity'].' × '.$line['item']['name']) ?></span><strong><?= Money::display($line['amount']) ?></strong></p><?php endforeach;?><p class="php-total"><strong>Items subtotal</strong><strong><?= Money::display($quote['subtotal']) ?></strong></p><p class="php-total"><span>Delivery charge</span><strong data-delivery-fee><?= $deliveryState['fee']!==null?money(Money::decimal($deliveryState['fee'])):'Enter pincode / choose area' ?></strong></p><p class="php-total"><strong>Estimated total</strong><strong data-delivery-total><?= money(Money::decimal($quote['subtotal']+($deliveryState['fee']??0))) ?></strong></p><p>Delivery and any applicable taxes are confirmed when you review your order.</p><a href="/cart/">Edit your cart →</a></aside></div></section>

<div class="checkout-action-bar" role="region" aria-label="Continue checkout"><div class="wrap checkout-action-inner"><p><strong>Ready to order?</strong><span>Review your final total, then confirm your order.</span></p><button class="btn btn-primary btn-lg" type="submit" form="delivery-details" <?= !$choices?'disabled':'' ?>>Review &amp; place order →</button></div></div>

<script src="<?= e(asset_url('checkout-delivery.js')) ?>" defer></script>
